import re
import urllib.request
import json

# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

def task_func(API_URL):
    try:
        # Make the API request
        with urllib.request.urlopen(API_URL, timeout=10) as response:
            data = response.read().decode('utf-8')

        # Try to parse as JSON first (common for IP APIs)
        try:
            json_data = json.loads(data)
            # Common API response formats for IP
            ip = json_data.get('ip') or json_data.get('ipAddress') or json_data.get('address')

            if ip:
                # Validate IP format
                if re.match(IP_REGEX, ip):
                    return ip
        except json.JSONDecodeError:
            pass

        # If not JSON, try to find IP in response text
        match = re.search(IP_REGEX, data)
        if match:
            return match.group(0)

        # If no IP found in response
        raise ValueError("No valid IP address found in API response")

    except urllib.error.URLError as e:
        raise Exception(f"API request failed: {str(e.reason)}")
    except Exception as e:
        raise Exception(f"Error: {str(e)}")
